<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)($_GET['id']??$u['id']);$q=db()->prepare('SELECT u.id,u.name,u.email,p.* FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE u.id=? AND u.status=\'active\'');$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Student not found');}$skills=db()->prepare('SELECT s.name FROM user_skills x JOIN skills s ON s.id=x.skill_id WHERE x.user_id=?');$skills->execute([$id]);$subjects=db()->prepare('SELECT s.name,x.intent FROM user_subjects x JOIN subjects s ON s.id=x.subject_id WHERE x.user_id=?');$subjects->execute([$id]);page_start('My Profile'); ?><div class="card"><div class="card-body p-4"><div class="d-flex gap-4 align-items-center"><div class="avatar avatar-lg"><?= e(mb_substr($p['name'],0,1)) ?></div><div><h2><?= e($p['name']) ?></h2><div class="text-secondary"><?= e($p['course']) ?> · Semester <?= e($p['semester']) ?> · <?= e($p['college']) ?></div><div class="mt-2">★ <?= e(rating_avg($id)) ?> rating</div></div><?php if($id===(int)$u['id']): ?><a class="btn btn-outline-primary ms-auto" href="edit-profile.php">Edit profile</a><?php else: ?><a class="btn btn-primary ms-auto" href="partner-details.php?id=<?= $id ?>">Connect</a><?php endif ?></div><hr><h3 class="h5">About</h3><p><?= nl2br(e($p['about']?:'Add an introduction to help other students get to know you.')) ?></p><h3 class="h5 mt-4">Learning goals</h3><p><?= nl2br(e($p['learning_goals']?:'Not added yet.')) ?></p><div class="row"><div class="col-md-6"><h3 class="h6 mt-3">Skills</h3><?php foreach($skills as $x)echo tag($x['name']); ?></div><div class="col-md-6"><h3 class="h6 mt-3">Subjects</h3><?php foreach($subjects as $x)echo tag($x['name'].' · '.($x['intent']==='help'?'Can help':'Want to learn')); ?></div></div><p class="mt-4 mb-0"><strong>Study mode:</strong> <?= e($p['study_mode']?:'Not set') ?> · <strong>Availability:</strong> <?= e($p['availability_days']?:'Not set') ?> <?= $p['start_time']?' · '.e(substr($p['start_time'],0,5)).'–'.e(substr($p['end_time'],0,5)):'' ?> · <strong>Languages:</strong> <?= e($p['languages']?:'Not set') ?></p></div></div><?php page_end(); ?>
